  if (sty==='ghost')     return { g:[236,60,7], panel:[234,52,11], mark:[H,24,98], grid:[H,50,30], anno:[H,16,86], ctr:[12,70,58], grain:16, add:true, wash:[H,44,60], warp:[[H,58,68],[H+30,52,56]], weft:[[H+170,50,64],[H+150,44,52]] };
