const fc = (c,a) => { fill(hw(c[0]), c[1], c[2], a*AL); };
const draft = (sty==='draft');

// ---- the loom clock: picks are emitted in real time, rate wanders ------------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const wob = 1 + .22*Math.sin(K.t*.127) + .13*Math.sin(K.t*.311+1.4) + .07*Math.sin(K.t*.743+2.7);
