// ---- geometry: `scale` sets the SETT (thread coarseness); counts follow ------
const mgn = u*.028;
const BC = Math.round(cl(u*.0165*cl(P.scale,.35,2.4), 4, 26));
const availW = width - mgn*4.2, availH = height - mgn*4.6;
const Sh = 4 + Math.floor(cl(P.density,0,1)*4.99);        // shafts 4..8
const Td = Sh;                                            // treadles
let E = Math.floor(availW/BC) - 1 - Td;                   // warp ends
let Pk = Math.floor(availH/BC) - 1 - Sh;                  // picks shown
E = cl(E, 8, 220); Pk = cl(Pk, 8, 220);
const COLS = E + 1 + Td, ROWS = Sh + 1 + Pk;

// ---- draft: threading / tie-up / treadling, each re-drafted on its own clock -
const gT = S.genT||0, gU = S.genU||0, gL = S.genL||0;
const thrMode = Math.floor(fg(1.7, gT)*3)%3;
const tieMode = Math.floor(fg(2.9, gU)*3)%3;
const trdMode = Math.floor(fg(4.3, gL)*3)%3;
const MODEN = ['STRAIGHT','POINT','BLOCK'];
function threading(i){
  if (thrMode===0) return i % Sh;                                        // straight draw
  if (thrMode===1){ const p2 = 2*Sh-2; const j = i % p2; return j < Sh ? j : p2 - j; }  // point twill
  const blk = Math.floor(i/Math.max(2, 2 + Math.floor(fg(9.1,gT)*3)));   // block draft
  return Math.floor(fg(blk*3.13+5.7, gT)*Sh) % Sh;
}
function treadling(i){
  if (trdMode===0) return i % Td;
  if (trdMode===1){ const p2 = 2*Td-2; const j = ((i%p2)+p2)%p2; return j < Td ? j : p2 - j; }
  return threading(i);                                                   // tromp as writ
}
// P.sett = how many shafts lift per treadle: the real 1/3-twill (weft-faced) .. 3/1-twill (warp-faced) axis
const LIFTS = cl(Math.round(Sh*cl(P.sett,0,1)), 1, Sh-1);
function tieup(t,s){
  if (tieMode===0) return ((s - t + Sh*4) % Sh) < LIFTS;                   // N/M twill
  if (tieMode===1) return ((s - t + Sh*4) % Sh) < 1 || ((s - t + Sh*4) % Sh) === Math.floor(Sh/2); // satin-ish
  return fg(t*7.7 + s*3.1 + 11, gU) < (.18 + .64*cl(P.sett,0,1));          // seeded, biased by sett
}
const lift = (pick, end) => tieup(((treadling(pick)%Td)+Td)%Td, threading(end)) ? 1 : 0;
const warpCol = e => C.warp[Math.floor(fg(Math.floor(e/(2+Math.floor(fr(6.1)*5)))*2.7+3, 0)*C.warp.length) % C.warp.length];
const weftCol = p2 => C.weft[Math.floor(fg(Math.floor(p2/(2+Math.floor(fr(8.3)*6)))*5.1+9, 0)*C.weft.length) % C.weft.length];

// ---- cell painter (shared by the cloth buffer and the head buffer) -----------
function cell(g, x, y, c, up, e, p2){
