  g.fill(h2, cl(s2,0,100), cl(b2*.80,0,100), 100); g.rect(x, y, c, c);
  // the float reads as a real thread: shadow edge, body, specular highlight along the axis
  if (up){
    g.fill(h2, sEdge, bEdge, 100); g.rect(x, y, c*.17, c);
    g.fill(h2, sLit, bLit, 100);   g.rect(x + c*.30, y, c*.24, c);
    g.fill(h2, sMid, bMid, 100);   g.rect(x + c*.80, y, c*.20, c);
