// ---- buffers ----------------------------------------------------------------
const bkey = sd+'|'+sty+'|'+BC+'|'+E+'|'+Pk+'|'+Sh+'|'+LIFTS+'|'+cl(P.sett,0,1).toFixed(2)+'|'+gT+'|'+gU+'|'+gL+'|'+H.toFixed(0);
