    g2.noStroke(); g2.fill(hw(C.panel[0]), C.panel[1], C.panel[2], 100); g2.rect((E+1+t2)*BC, s2*BC, BC, BC);
    if (on){ g2.fill(hw(C.mark[0]), C.mark[1], C.mark[2], 100); g2.rect((E+1+t2)*BC+BC*.14, s2*BC+BC*.14, BC*.72, BC*.72); }
    g2.noFill(); g2.stroke(hw(C.grid[0]), C.grid[1], C.grid[2], 46); g2.strokeWeight(Math.max(.4,BC*.05));
