rect(ox+(E+1)*BC, hy, Td*BC, Sh*BC);             // tie-up box
rect(ox, cy, E*BC, Pk*BC);                       // drawdown box
rect(ox+(E+1)*BC, cy, Td*BC, Pk*BC);             // treadling box
