  textAlign(RIGHT, BOTTOM); text('TIE-UP - '+MODEN[tieMode], ox+DW, hy-u*.006);
  textAlign(LEFT, TOP);     text('DRAWDOWN', ox, cy + Pk*BC + u*.022);
  push(); translate(ox+DW+u*.014, cy+Pk*BC*.5); rotate(-Math.PI/2);
  textAlign(CENTER, BOTTOM); text('TREADLING - '+MODEN[trdMode], 0, 0); pop();
  // shaft + treadle numbering
  textSize(Math.max(4, Math.min(u*.0095, BC*.62))); fc(C.anno, 54+30*anno);
  textAlign(RIGHT, CENTER);
  for (let s2=0;s2<Sh;s2++) text(''+(Sh-s2), ox-u*.005, hy+s2*BC+BC*.5);
  textAlign(CENTER, BOTTOM);
  for (let t2=0;t2<Td;t2++) text(''+(t2+1), ox+(E+1+t2)*BC+BC*.5, hy-u*.002);
